/// Host/device transfer counters attached to a FEM evidence packet.
///
/// The counters are deliberately operation counts and bytes rather than a
/// profiler substitute. They make accidental per-frequency uploads or full
/// solution readbacks visible in a portable manifest.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct FemTransferStats {
    pub h2d_operations: usize,
    pub h2d_bytes: usize,
    pub d2h_operations: usize,
    pub d2h_bytes: usize,
    pub d2d_operations: usize,
    pub d2d_bytes: usize,
}

impl FemTransferStats {
    pub fn saturating_sub(self, earlier: Self) -> Self {
        Self {
            h2d_operations: self.h2d_operations.saturating_sub(earlier.h2d_operations),
            h2d_bytes: self.h2d_bytes.saturating_sub(earlier.h2d_bytes),
            d2h_operations: self.d2h_operations.saturating_sub(earlier.d2h_operations),
            d2h_bytes: self.d2h_bytes.saturating_sub(earlier.d2h_bytes),
            d2d_operations: self.d2d_operations.saturating_sub(earlier.d2d_operations),
            d2d_bytes: self.d2d_bytes.saturating_sub(earlier.d2d_bytes),
        }
    }
}

impl From<TransferStatsSnapshot> for FemTransferStats {
    fn from(stats: TransferStatsSnapshot) -> Self {
        Self {
            h2d_operations: stats.h2d_operations,
            h2d_bytes: stats.h2d_bytes,
            d2h_operations: stats.d2h_operations,
            d2h_bytes: stats.d2h_bytes,
            d2d_operations: stats.d2d_operations,
            d2d_bytes: stats.d2d_bytes,
        }
    }
}

