/// A physical-domain P1 FEM pressure field retained for spatial export.
///
/// The runner normally keeps only listener interpolations to minimize memory.
/// This opt-in result retains the accepted complex nodal solution for every
/// source and frequency together with the exact mesh used by the solve.
/// `listener_positions` records the exact receiver coordinates used to
/// produce the companion [`SimulationOutput`]. Values are indexed
/// `[source][frequency][node]`.
#[derive(Debug, Clone)]
pub struct FemNodalField {
    pub mesh: Mesh,
    pub frequencies: Vec<f64>,
    pub source_names: Vec<String>,
    pub listener_positions: Vec<Point3D>,
    pub pressures: Vec<Vec<Vec<Complex64>>>,
}

impl FemNodalField {
    pub fn validate(&self) -> Result<(), String> {
        if self.frequencies.is_empty()
            || self
                .frequencies
                .iter()
                .any(|frequency| !frequency.is_finite() || *frequency <= 0.0)
            || self
                .frequencies
                .windows(2)
                .any(|window| window[1] <= window[0])
        {
            return Err(
                "FEM nodal field frequencies must be finite, positive, and increasing".into(),
            );
        }
        if self.mesh.nodes.is_empty() {
            return Err("FEM nodal field mesh has no nodes".into());
        }
        if self.listener_positions.is_empty()
            || self.listener_positions.iter().any(|position| {
                !position.x.is_finite() || !position.y.is_finite() || !position.z.is_finite()
            })
        {
            return Err("FEM nodal field listener positions must be finite and non-empty".into());
        }
        if self.source_names.len() != self.pressures.len() {
            return Err("FEM nodal field source names and pressure fields differ in length".into());
        }
        for (source_index, source) in self.pressures.iter().enumerate() {
            if source.len() != self.frequencies.len() {
                return Err(format!(
                    "FEM nodal field source {source_index} has {} frequencies, expected {}",
                    source.len(),
                    self.frequencies.len()
                ));
            }
            for (frequency_index, values) in source.iter().enumerate() {
                if values.len() != self.mesh.nodes.len() {
                    return Err(format!(
                        "FEM nodal field source {source_index} frequency {frequency_index} has {} nodes, expected {}",
                        values.len(),
                        self.mesh.nodes.len()
                    ));
                }
                if values
                    .iter()
                    .any(|value| !value.re.is_finite() || !value.im.is_finite())
                {
                    return Err(format!(
                        "FEM nodal field source {source_index} frequency {frequency_index} contains non-finite pressure"
                    ));
                }
            }
        }
        Ok(())
    }

    /// Interpolate one retained P1 nodal field at physical tetrahedral points.
    pub fn sample_p1(
        &self,
        source_index: usize,
        frequency_index: usize,
        positions: &[Point3D],
    ) -> Result<Vec<Complex64>, String> {
        self.validate()?;
        let values = self
            .pressures
            .get(source_index)
            .and_then(|source| source.get(frequency_index))
            .ok_or_else(|| {
                format!(
                    "FEM nodal field index out of range: source {source_index}, frequency {frequency_index}"
                )
            })?;
        if positions.is_empty() {
            return Err("FEM nodal field sampling requires at least one position".into());
        }
        let containing_elements: Vec<Option<usize>> = positions
            .iter()
            .map(|&position| find_containing_element_parallel(&self.mesh, position))
            .collect();
        if let Some(index) = containing_elements.iter().position(Option::is_none) {
            return Err(format!(
                "FEM nodal field sample position {index} lies outside the physical mesh"
            ));
        }
        let (interpolations, fallback_count) =
            build_listener_interpolations(&self.mesh, positions, &containing_elements);
        if fallback_count > 0 {
            log::warn!(
                "FEM nodal field sampling fell back to nearest-node interpolation for {fallback_count} position(s)"
            );
        }
        Ok(interpolations
            .iter()
            .map(|interpolation| {
                interpolation
                    .nodes
                    .iter()
                    .zip(interpolation.weights)
                    .map(|(&node, weight)| values[node] * weight)
                    .sum()
            })
            .collect())
    }

    /// Export one genuine FEM nodal solution as a VTU with real/imaginary and
    /// magnitude point fields. CSV/gallery slices should be derived from this
    /// same retained solution, never from listener-response rasterization.
    pub fn write_vtu(
        &self,
        path: impl AsRef<std::path::Path>,
        source_index: usize,
        frequency_index: usize,
    ) -> Result<(), String> {
        self.validate()?;
        let values = self
            .pressures
            .get(source_index)
            .and_then(|source| source.get(frequency_index))
            .ok_or_else(|| {
                format!(
                    "FEM nodal field index out of range: source {source_index}, frequency {frequency_index}"
                )
            })?;
        let mut writer = sonium_xem::io::vtu::VtuWriter::new(&self.mesh);
        writer.add_point_scalar_complex("pressure", values);
        writer.write(path).map_err(|error| error.to_string())
    }
}

#[derive(Clone, Debug)]
pub(super) struct SourceRhsBasis {
    /// Nodal source weights and their world positions. Directivity is applied
    /// here, before propagation, so reflected energy inherits the source
    /// radiation pattern.
    pub(super) entries: Vec<(usize, f64, Point3D)>,
    pub(super) scale_base: f64,
}

/// Complex source amplitude for the room FEM's `exp(-iωt)` convention.
///
/// [`Source::complex_isotropic_amplitude`](sonium_xem::Source::complex_isotropic_amplitude)
/// is evaluated with the opposite Fourier sign, so the room-side transfer
/// function must be conjugated before it is combined with the `-iωρ` source
/// scale and the FEM operator.
pub(super) fn room_complex_isotropic_amplitude(source: &Source, frequency: f64) -> Complex64 {
    source.complex_isotropic_amplitude(frequency).conj()
}

