/// Per-frequency FEM boundary mass coefficients keyed by physical room face.
///
/// Each value is the complex Robin coefficient multiplying the corresponding
/// boundary mass integral in the Helmholtz weak form.
#[derive(Debug, Clone, Copy)]
pub struct FemBoundaryCoefficients {
    pub floor: Complex64,
    pub ceiling: Complex64,
    pub front: Complex64,
    pub back: Complex64,
    pub left: Complex64,
    pub right: Complex64,
}

pub(super) fn boundary_for_room_point<'a>(
    room: &RoomGeometry,
    boundaries: &'a ResolvedBoundaries,
    point: Point3D,
) -> &'a ResolvedBoundary {
    let (width, depth, height) = room.dimensions();
    let eps = 1.0e-7 * width.max(depth).max(height).max(1.0);

    if point.z.abs() <= eps {
        &boundaries.floor
    } else if (point.z - height).abs() <= eps {
        &boundaries.ceiling
    } else if point.y.abs() <= eps {
        &boundaries.front
    } else if (point.y - depth).abs() <= eps {
        &boundaries.back
    } else if point.x.abs() <= eps {
        &boundaries.left
    } else if (point.x - width).abs() <= eps {
        &boundaries.right
    } else {
        &boundaries.walls
    }
}

/// Compute the same per-face FEM boundary coefficients used by the internal
/// Helmholtz assembler. This is intended for external reference-solver
/// comparisons, where the generated problem must use Sonium's resolved
/// material model rather than reimplementing absorption/porous conversion.
#[deprecated(note = "panics on invalid input; use try_fem_boundary_coefficients")]
pub fn fem_boundary_coefficients(
    simulation: &RoomSimulation,
    frequency: f64,
) -> FemBoundaryCoefficients {
    try_fem_boundary_coefficients(simulation, frequency).expect("invalid FEM boundary coefficient")
}

/// Checked boundary coefficients; material errors are returned before assembly.
pub fn try_fem_boundary_coefficients(
    simulation: &RoomSimulation,
    frequency: f64,
) -> anyhow::Result<FemBoundaryCoefficients> {
    let boundaries = resolve_boundaries(simulation)?;
    let k = simulation.wavenumber(frequency);
    Ok(FemBoundaryCoefficients {
        floor: boundaries.floor.admittance_term(k, frequency)?,
        ceiling: boundaries.ceiling.admittance_term(k, frequency)?,
        front: boundaries.front.admittance_term(k, frequency)?,
        back: boundaries.back.admittance_term(k, frequency)?,
        left: boundaries.left.admittance_term(k, frequency)?,
        right: boundaries.right.admittance_term(k, frequency)?,
    })
}

#[cfg(test)]
pub(super) fn assemble_rhs_from_basis(
    basis: &SourceRhsBasis,
    source: &Source,
    frequency: f64,
    n_dofs: usize,
) -> Vec<Complex64> {
    let mut rhs = vec![Complex64::new(0.0, 0.0); n_dofs];
    assemble_rhs_from_basis_into(basis, source, frequency, &mut rhs);
    rhs
}

pub(super) fn assemble_rhs_from_basis_into(
    basis: &SourceRhsBasis,
    source: &Source,
    frequency: f64,
    rhs: &mut [Complex64],
) {
    rhs.fill(Complex64::new(0.0, 0.0));
    let mut coefficients = vec![Complex64::new(0.0, 0.0); basis.entries.len()];
    assemble_source_coefficients_into(basis, source, frequency, &mut coefficients);
    for (&(node_idx, _, _), &coefficient) in basis.entries.iter().zip(&coefficients) {
        rhs[node_idx] += coefficient;
    }
}

/// Build the per-basis-entry source coefficients used by device-side RHS
/// assembly. The source model/directivity and source-basis weighting stay on
/// the host; the device-side matrix performs only the sparse accumulation.
pub(super) fn assemble_source_coefficients_into(
    basis: &SourceRhsBasis,
    source: &Source,
    frequency: f64,
    coefficients: &mut [Complex64],
) {
    assert_eq!(coefficients.len(), basis.entries.len());
    coefficients.fill(Complex64::new(0.0, 0.0));
    let q = room_complex_isotropic_amplitude(source, frequency);
    if q.norm() == 0.0 || basis.entries.is_empty() {
        return;
    }

    let omega = 2.0 * std::f64::consts::PI * frequency;
    let scale = Complex64::new(0.0, -omega * basis.scale_base) * q;
    for (coefficient, &(_, weight, point)) in coefficients.iter_mut().zip(&basis.entries) {
        let directivity = source.complex_directivity_factor(&point, frequency);
        *coefficient = scale * directivity * weight;
    }
}

pub(super) fn evaluate_listener_interpolation(
    solution: &[Complex64],
    interpolation: &ListenerInterpolation,
) -> Complex64 {
    solution[interpolation.nodes[0]] * interpolation.weights[0]
        + solution[interpolation.nodes[1]] * interpolation.weights[1]
        + solution[interpolation.nodes[2]] * interpolation.weights[2]
        + solution[interpolation.nodes[3]] * interpolation.weights[3]
}

#[cfg(test)]
mod tests {
    use super::*;
    use sonium_fem::mesh::{ElementType, Point};

    #[test]
    fn nodal_field_p1_sampling_recovers_linear_pressure() {
        let mut mesh = Mesh::new(3);
        for point in [
            Point::new_3d(0.0, 0.0, 0.0),
            Point::new_3d(1.0, 0.0, 0.0),
            Point::new_3d(0.0, 1.0, 0.0),
            Point::new_3d(0.0, 0.0, 1.0),
        ] {
            mesh.add_node(point);
        }
        mesh.add_element(ElementType::Tetrahedron, vec![0, 1, 2, 3]);
        let field = FemNodalField {
            mesh,
            frequencies: vec![100.0],
            source_names: vec!["source".into()],
            listener_positions: vec![Point3D::new(0.25, 0.25, 0.25)],
            pressures: vec![vec![vec![
                Complex64::new(1.0, 0.0),
                Complex64::new(2.0, 0.0),
                Complex64::new(3.0, 0.0),
                Complex64::new(4.0, 0.0),
            ]]],
        };
        let samples = field
            .sample_p1(0, 0, &[Point3D::new(0.25, 0.25, 0.25)])
            .unwrap();
        assert!((samples[0].re - 2.5).abs() < 1.0e-12);
        assert_eq!(samples[0].im, 0.0);
    }

    #[test]
    fn nodal_field_rejects_samples_outside_mesh() {
        let mut mesh = Mesh::new(3);
        for point in [
            Point::new_3d(0.0, 0.0, 0.0),
            Point::new_3d(1.0, 0.0, 0.0),
            Point::new_3d(0.0, 1.0, 0.0),
            Point::new_3d(0.0, 0.0, 1.0),
        ] {
            mesh.add_node(point);
        }
        mesh.add_element(ElementType::Tetrahedron, vec![0, 1, 2, 3]);
        let field = FemNodalField {
            mesh,
            frequencies: vec![100.0],
            source_names: vec!["source".into()],
            listener_positions: vec![Point3D::new(0.25, 0.25, 0.25)],
            pressures: vec![vec![vec![Complex64::new(1.0, 0.0); 4]]],
        };
        assert!(
            field
                .sample_p1(0, 0, &[Point3D::new(1.0, 1.0, 1.0)])
                .is_err()
        );
    }

    #[test]
    fn nodal_field_validation_requires_finite_listener_positions() {
        let mut mesh = Mesh::new(3);
        for point in [
            Point::new_3d(0.0, 0.0, 0.0),
            Point::new_3d(1.0, 0.0, 0.0),
            Point::new_3d(0.0, 1.0, 0.0),
            Point::new_3d(0.0, 0.0, 1.0),
        ] {
            mesh.add_node(point);
        }
        mesh.add_element(ElementType::Tetrahedron, vec![0, 1, 2, 3]);
        let mut field = FemNodalField {
            mesh,
            frequencies: vec![100.0],
            source_names: vec!["source".into()],
            listener_positions: vec![Point3D::new(0.25, 0.25, 0.25)],
            pressures: vec![vec![vec![Complex64::new(1.0, 0.0); 4]]],
        };
        assert!(field.validate().is_ok());
        field.listener_positions[0].x = f64::NAN;
        assert!(field.validate().unwrap_err().contains("listener positions"));
    }
}
